void construct_path(char *name, int lenmax, off_t size, off_t pos, off_t *ppos) {
	int pathlen = strlen(name);
	char *path = name + pathlen;
	int remaining = lenmax - pathlen;
	off_t block = pos / TREEPAGESIZE;
	int depth = get_tree_depth(size);

