/* depth: number of TRE directory levels */
static int get_tree_depth(off_t size)
{
	int depth = 0;
	unsigned long long capacity = TREEDIRSIZE;   /* number of blocks at depth 0 */
	unsigned long long nblocks = (size + TREEPAGESIZE - 1) / TREEPAGESIZE;

	while (capacity < nblocks) {
		capacity *= TREEDIRSIZE;
		depth++;
	}
	return depth;
}
```

