void construct_path(char *name, int lenmax, off_t size, off_t pos, off_t *ppos)
{
	int depth = get_tree_depth(size);
	off_t block = pos / TREEPAGESIZE;
	int off = strlen(name);

	assert(pos >= 0);
	assert(pos < size);

	*ppos = pos % TREEPAGESIZE;

	for (int i = depth; i > 0; i--) {
		off_t divisor = 1;
		for (int j = 1; j < i; j++)
			divisor *= TREEDIRSIZE;
		off_t idx = (block / (divisor * TREEDIRSIZE)) % TREEDIRSIZE;
		off += snprintf(name + off, lenmax - off, "/TRE%04d", (int)idx);
	}
	snprintf(name + off, lenmax - off, "/FIL%04d", (int)(block % TREEDIRSIZE));
}
```

