Now write treefiles.c completely:

```c
/*
 * Tree files support for nbd-server.
 *
 * When an export is configured with the treefiles option, the exported
 * data is stored in a tree of small files rather than in a single large
 * file. The root of the tree is the directory named by the export name.
 * The export is split into blocks of TREEPAGESIZE bytes; each block
 * lives in its own file. Each directory holds at most TREEDIRSIZE files
 * or subdirectories, so an appropriate number of subdirectory levels is
 * created to cover the size of the export:
 *
 *   exportname/TRE0000/.../TRE1023/FIL0000 ... FIL1023
 *
 * Blocks which have never been written to (or which have been trimmed)
 * have no file and read back as all zeroes. This makes the tree sparse:
 * only blocks that were actually written consume space.
 */

#include "config.h"
#include "nbd-debug.h"

#include <nbdsrv.h>

#include <assert.h>
#include <errno.h>
#include <fcntl.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#include <sys/stat.h>
#include <sys/types.h>

#include <backend.h>
#include <cliserv.h>

#include "treefiles.h"

/* Maximal length of the tree path appended to the export name:
 * one "/TREdddd" component per directory level plus "/FILdddd".
 * An off_t-sized export needs at most 6 directory levels. */
#define TREEPATHMAX 64
```

