Functions:

```c
/**
 * Compute the number of subdirectory levels required to store an
 * export of the given size in files of TREEPAGESIZE bytes each, with
 * at most TREEDIRSIZE entries per directory.
 *
 * @param size the size of the export
 * @return the number of subdirectory levels
 **/
static int get_tree_depth(off_t size) {
	int depth = 0;
	unsigned long long capacity = TREEPAGESIZE;

	while(capacity < (unsigned long long)size) {
		capacity *= TREEDIRSIZE;
		depth++;
	}
	return depth;
}
```

