```c
/**
 * Open the tree file holding the byte at position pos of the export
 * rooted at name.
 *
 * @param name name of the export (the root directory of the tree)
 * @param mode file status flags for open(2); when O_CREAT is included,
 * any missing directories and the file itself are created
 * @param size total size of the export
 * @param pos position within the export
 * @param mutex mutex serialising the creation of tree directories
 * @return a file descriptor for the tree file, or -1 if the tree file
 * could not be opened (errno is set; ENOENT when reading a block which
 * has never been written)
 **/
int open_treefile(char *name, mode_t mode, off_t size, off_t pos, pthread_mutex_t *mutex) {
	char path[strlen(name) + TREEPATHMAX];
	char dir[strlen(name) + TREEPATHMAX];
	char *sep;
	off_t ppos;
	int fd;

	strcpy(path, name);
	construct_path(path, sizeof(path), size, pos, &ppos);
	if(mode & O_CREAT) {
		strcpy(dir, path);
		sep = strrchr(dir, '/');
		if(sep && sep != dir) {
			*sep = '\0';
			pthread_mutex_lock(mutex);
			mkdir_path(dir);
			pthread_mutex_unlock(mutex);
		}
	}
	do {
		fd = open(path, mode, 0600);
	} while(fd < 0 && errno == EINTR);

	return fd;
}
```

