ssize_t treeexpwrite(CLIENT *client, off_t a, char *buf, size_t len, int fua) {
	size_t written = 0;

	if(a + (off_t)len > (off_t)client->exportsize) {
		len = (size_t)((off_t)client->exportsize - a);
	}
	while(written < len) {
		off_t pos = a + written;
		off_t ppos = pos % TREEPAGESIZE;
		size_t chunk = len - written;
		int fd;
		ssize_t w = 0;

		if(chunk > (size_t)(TREEPAGESIZE - ppos)) {
			chunk = TREEPAGESIZE - ppos;
		}
		fd = open_treefile(client->exportname, O_RDWR | O_CREAT, client->exportsize, pos, &client->treefiles_lock);
		if(fd < 0) {
			return written ? (ssize_t)written : -1;
		}
		while(w < (ssize_t)chunk) {
			ssize_t ret = pwrite(fd, buf + written + w, chunk - w, ppos + w);
			if(ret < 0) {
				if(errno == EINTR) continue;
				close(fd);
				return written ? (ssize_t)written : -1;
			}
			w += ret;
