		if(client->server->flags & F_SYNC) {
			fsync(fd);
		} else if(fua || (client->server->flags & F_FLUSH)) {
			fdatasync(fd);
		}
		close(fd);
		written += chunk;
	}
	return (ssize_t)written;
}
