int treetrim(CLIENT *client, off_t from, size_t len) {
	off_t pos = from;
	off_t end = from + (off_t)len;

	while(pos < end) {
		off_t blockstart = pos - (pos % TREEPAGESIZE);
		off_t blockend = blockstart + TREEPAGESIZE;
		off_t stop = end < blockend ? end : blockend;

		if(pos == blockstart && stop == blockend) {
			pthread_mutex_lock(&client->treefiles_lock);
			delete_treefile(client->exportname, client->exportsize, blockstart);
			pthread_mutex_unlock(&client->treefiles_lock);
		} else {
			int fd = open_treefile(client->exportname, O_RDWR, client->exportsize, blockstart, &client->treefiles_lock);
			if(fd >= 0) {
				punch_hole(fd, pos - blockstart, stop - pos);
				close(fd);
			} else if(errno != ENOENT) {
				return -1;
			}
		}
		pos = stop;
	}
	return 0;
}
