arguments.content:
/*
 * Tree files support for nbd-server.
 *
 * When an export is configured with the treefiles option, the exported
 * data is stored in a tree of small files rather than in one large
 * file; the root of the tree is the directory named by the exportname.
 * The export is split into blocks of TREEPAGESIZE bytes, each of which
 * is stored in its own file. No directory contains more than
 * TREEDIRSIZE files or subdirectories, so just enough levels of
 * subdirectories are created to cover the total size of the export:
 *
 * exportname/TRE0000/.../TRE1023/FIL0000 ... exportname/.../FIL1023
 *
 * Blocks which have never been written (or which have been trimmed
 * away entirely) have no corresponding file and read back as zeroes,
 * so the tree is sparse: only blocks which were actually written to
 * consume disk space. Files are opened on demand, which makes this
 * backend usable on filesystems which do not handle large files well
 * (fuse/ftpfs, davfs and other network filesystems).
 */

#include "config.h"
#include "nbd-debug.h"

#include <nbdsrv.h>

#include <assert.h>
#include <errno.h>
#include <fcntl.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <unistd.h>

#include <sys/stat.h>
#include <sys/types.h>

#include <backend.h>
#include <cliserv.h>

#include "treefiles.h"

/** Maximal length of the tree path appended to the export name: one
 * "/TREdddd" component per directory level plus a final "/FILdddd".
 * Covering an off_t-sized export needs at most 6 directory levels,
 * so 64 bytes leaves some headroom. */
#define TREEPATHMAX 64

/**
 * Compute the number of subdirectory levels required to store an
 * export of the given size in files of TREEPAGESIZE bytes each, with
 * at most TREEDIRSIZE entries per directory.
 *
 * @param size the size of the export
 * @return the number of subdirectory levels below the tree root
 **/
static int get_tree_depth(off_t size) {
	int depth = 0;
	unsigned long long capacity = TREEPAGESIZE;

	while(capacity < (unsigned long long)size) {
		capacity *= TREEDIRSIZE;
		depth++;
	}
	return depth;
}

/**
 * Compute the path of the tree file holding the byte at position pos
 * of an export of the given size, and append it to name.
 *
 * @param name buffer holding the name of the export (the root of the
 * tree); the path of the tree file is appended to it
 * @param lenmax total size of the name buffer
 * @param size total size of the export
 * @param pos position within the export
 * @param ppos position within the tree file of the byte at pos
 **/
void construct_path(char *name, int lenmax, off_t size, off_t pos, off_t *ppos) {
	int depth = get_tree_depth(size);
	off_t block = pos / TREEPAGESIZE;
	int len = strlen(name);
	int i;

	assert(pos >= 0);
	assert(pos < size);
	assert(lenmax >= len + TREEPATHMAX);

	*ppos = pos % TREEPAGESIZE;

	for(i = depth; i > 0; i--) {
		off_t divisor = 1;
		int j;

		for(j = 0; j < i; j++) {
			divisor *= TREEDIRSIZE;
		}
		len += snprintf(name + len, lenmax - len, "/TRE%04d",
				(int)((block / divisor) % TREEDIRSIZE));
	}
	snprintf(name + len, lenmax - len, "/FIL%04d",
		 (int)(block % TREEDIRSIZE));
}

/**
 * Create the directory named by path, along with any missing parent
 * directories. The path argument is temporarily modified while the
 * path is walked.
 *
 * @param path the directory to create
 **/
void mkdir_path(char *path) {
	char *p;

	p = path[0] == '/' ? path + 1 : path;
	for(p = strchr(p, '/'); p; p = strchr(p + 1, '/')) {
		*p = '\0';
		if(mkdir(path, 0700) && errno != EEXIST) {
			msg(LOG_ERR, "Could not create directory %s: %s",
			    path, strerror(errno));
			*p = '/';
			return;
		}
		*p = '/';
	}
	if(mkdir(path, 0700) && errno != EEXIST) {
		msg(LOG_ERR, "Could not create directory %s: %s",
		    path, strerror(errno));
	}
}

/**
 * Open the tree file holding the byte at position pos of the export
 * rooted at name.
 *
 * @param name name of the export (the root directory of the tree)
 * @param mode file status flags for open(2); when O_CREAT is included,
 * any missing directories and the file itself are created
 * @param size total size of the export
 * @param pos position within the export
 * @param mutex mutex serialising the creation of tree directories
 * @return a file descriptor for the tree file, or -1 if the tree file
 * could not be opened; errno is set, to ENOENT e.g. when attempting to
 * read a block which was never written to
 **/
int open_treefile(char *name, mode_t mode, off_t size, off_t pos, pthread_mutex_t *mutex) {
	char path[strlen(name) + TREEPATHMAX];
	char dir[strlen(name) + TREEPATHMAX];
	char *sep;
	off_t ppos;
	int fd;

	strcpy(path, name);
	construct_path(path, sizeof(path), size, pos, &ppos);
	if(mode & O_CREAT) {
		strcpy(dir, path);
		sep = strrchr(dir, '/');
		if(sep && *dir) {
			*sep = '\0';
			pthread_mutex_lock(mutex);
			mkdir_path(dir);
			pthread_mutex_unlock(mutex);
		}
	}
	do {
		fd = open(path, mode, 0600);
	} while(fd < 0 && errno == EINTR);

	return fd;
}

/**
 * Delete the tree file holding the byte at position pos of the export
 * rooted at name, if it exists.
 *
 * @param name name of the export (the root directory of the tree)
 * @param size total size of the export
 * @param pos position within the export
 **/
void delete_treefile(char *name, off_t size, off_t pos) {
	char path[strlen(name) + TREEPATHMAX];
	off_t ppos;

	strcpy(path, name);
	construct_path(path, sizeof(path), size, pos, &ppos);
	if(unlink(path) && errno != ENOENT) {
		msg(LOG_ERR, "Could not delete tree file %s: %s",
		    path, strerror(errno));
	}
}

/**
 * Read an amount of bytes at a given offset from a treefiles export.
 * Blocks without a tree file (never written or trimmed) read back as
 * zeroes.
 *
 * @param client The client we're serving for
 * @param a The offset where the read should start
 * @param buf A buffer to read into
 * @param len The size of buf
 * @return The number of bytes read, or -1 in case of an error
 **/
ssize_t treeexpread(CLIENT *client, off_t a, char *buf, size_t len) {
	size_t bytesread = 0;

	if(a + (off_t)len > (off_t)client->exportsize) {
		len = (size_t)((off_t)client->exportsize - a);
	}
	while(bytesread < len) {
		off_t pos = a + bytesread;
		off_t ppos = pos % TREEPAGESIZE;
		size_t chunk = len - bytesread;
		int fd;

		if(chunk > (size_t)(TREEPAGESIZE - ppos)) {
			chunk = TREEPAGESIZE - ppos;
		}
		DEBUG("(TREEFILES READ from %s offset %llu len %zu), ",
		      client->exportname, (unsigned long long)pos, chunk);
		fd = open_treefile(client->exportname, O_RDONLY,
				   (off_t)client->exportsize, pos,
				   &client->treefiles_lock);
		if(fd < 0) {
			if(errno != ENOENT) {
				return bytesread ? (ssize_t)bytesread : -1;
			}
			memset(buf + bytesread, 0, chunk);
		} else {
			ssize_t r = pread(fd, buf + bytesread, chunk, ppos);

			if(r < 0) {
				int saved_errno = errno;

				close(fd);
				errno = saved_errno;
				return bytesread ? (ssize_t)bytesread : -1;
			}
			if((size_t)r < chunk) {
				memset(buf + bytesread + r, 0, chunk - r);
			}
			close(fd);
		}
		bytesread += chunk;
	}
	return (ssize_t)bytesread;
}

/**
 * Write an amount of bytes at a given offset to a treefiles export,
 * creating tree files (and directories) as needed.
 *
 * @param client The client we're serving for
 * @param a The offset where the write should start
 * @param buf The buffer to write from
 * @param len The length of buf
 * @param fua Flag to indicate 'Force Unit Access'
 * @return The number of bytes written, or -1 in case of an error
 **/
ssize_t treeexpwrite(CLIENT *client, off_t a, char *buf, size_t len, int fua) {
	size_t written = 0;

	if(a + (off_t)len > (off_t)client->exportsize) {
		len = (size_t)((off_t)client->exportsize - a);
	}
	while(written < len) {
		off_t pos = a + written;
		off_t ppos = pos % TREEPAGESIZE;
		size_t chunk = len - written;
		ssize_t w = 0;
		int fd;

		if(chunk > (size_t)(TREEPAGESIZE - ppos)) {
			chunk = TREEPAGESIZE - ppos;
		}
		DEBUG("(TREEFILES WRITE to %s offset %llu len %zu fua %d), ",
		      client->exportname, (unsigned long long)pos, chunk, fua);
		fd = open_treefile(client->exportname, O_RDWR | O_CREAT,
				   (off_t)client->exportsize, pos,
				   &client->treefiles_lock);
		if(fd < 0) {
			return written ? (ssize_t)written : -1;
		}
		while(w < (ssize_t)chunk) {
			ssize_t ret;

			ret = pwrite(fd, buf + written + w, chunk - w,
				     ppos + w);
			if(ret < 0) {
				if(errno == EINTR) {
					continue;
				}
				close(fd);
				return written ? (ssize_t)written : -1;
			}
			w += ret;
		}
		if(client->server->flags & F_SYNC) {
			fsync(fd);
		} else if(fua || (client->server->flags & F_FLUSH)) {
			/* files are closed immediately after writing,
			 * so this is the only chance to honour flush
			 * requests */
			fdatasync(fd);
		}
		close(fd);
		written += chunk;
	}
	return (ssize_t)written;
}

/**
 * Handle a TRIM request on a treefiles export. Tree files of blocks
 * which are trimmed entirely are deleted; partially trimmed blocks
 * get a hole punched instead.
 *
 * @param client The client we're serving for
 * @param from The offset where the trim should start
 * @param len The length of the trim
 * @return 0 on success, nonzero on failure
 **/
int treetrim(CLIENT *client, off_t from, size_t len) {
	off_t pos = from;
	off_t end = from + (off_t)len;

	while(pos < end) {
		off_t blockstart = pos - (pos % TREEPAGESIZE);
		off_t blockend = blockstart + TREEPAGESIZE;
		off_t stop;

		if(blockend > (off_t)client->exportsize) {
			blockend = (off_t)client->exportsize;
		}
		stop = end < blockend ? end : blockend;
		if(pos == blockstart && stop == blockend) {
			pthread_mutex_lock(&client->treefiles_lock);
			delete_treefile(client->exportname,
					(off_t)client->exportsize, blockstart);
			pthread_mutex_unlock(&client->treefiles_lock);
		} else {
			int fd;

			fd = open_treefile(client->exportname, O_RDWR,
					   (off_t)client->exportsize,
					   blockstart,
